# -*- coding: utf-8 -*-
"""Generate api/embedded_html.py from index.html.

Run after any change to index.html:
    python tools/embed_html.py

This embeds the full page into the serverless function so Vercel's
Python runtime serves it via Flask (no dependence on static file copying).
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(ROOT, "index.html")
DST = os.path.join(ROOT, "api", "embedded_html.py")

with open(SRC, "r", encoding="utf-8") as f:
    html = f.read()

out = (
    "# -*- coding: utf-8 -*-\n"
    "# AUTO-GENERATED by tools/embed_html.py — do not edit by hand.\n"
    "# Regenerate after changing index.html: python tools/embed_html.py\n\n"
    "INDEX_HTML = {!r}\n".format(html)
)

with open(DST, "w", encoding="utf-8") as f:
    f.write(out)

print("embedded {} bytes -> {}".format(len(html.encode("utf-8")), DST))
